1. Crosswalk cd_mun_tse ↔︎ cd_mun
O TSE usa um código de município próprio (CD_MUNICIPIO), diferente do código IBGE de 7 dígitos usado no resto da GeoReDUS. Não existe crosswalk em nenhum dos nossos repos (ver PLAN.md &gt; Fontes de dados) — usamos a tabela pronta do projeto yuripassuelo/codigos_mun_tse_ibge, que já cruza os 5.570 municípios (sem o exterior).

caminho_crosswalk_bruto &lt;- "dados/01_bruto/aux/relacao_mun_tse_ibge.csv"
dir.create(dirname(caminho_crosswalk_bruto), showWarnings = FALSE, recursive = TRUE)

if (!file.exists(caminho_crosswalk_bruto)) {
  req &lt;- request(
    "https://raw.githubusercontent.com/yuripassuelo/codigos_mun_tse_ibge/master/relacao_mun_tse_ibge.csv"
  ) |&gt;
    req_retry(max_tries = 3, backoff = \(n) 2^n) |&gt;
    req_user_agent("dados_eleicoes (CEM/USP)")
  resp &lt;- req_perform(req)
  writeBin(resp_body_raw(resp), caminho_crosswalk_bruto)
}

crosswalk_bruto &lt;- read_csv(
  caminho_crosswalk_bruto,
  locale = locale(encoding = "latin1"),
  col_types = cols(.default = col_character())
)

crosswalk &lt;- crosswalk_bruto |&gt;
  transmute(
    # o CD_MUNICIPIO dos arquivos do TSE vem com 5 dígitos e zero à esquerda
    # (ex.: "01120"), mas o CSV de origem do crosswalk guarda cd_mun_tse sem
    # padding ("1120") — confirmado contra o arquivo real de locais em
    # 28/09/2026 (ver CLAUDE.md).
    cd_mun_tse = str_pad(cd_mun_tse, 5, pad = "0"),
    cd_mun = str_pad(cd_mun_ibge, 7, pad = "0"),
    sg_uf = SG_UF,
    nm_mun_ibge = nm_mun_ibge,
    nm_mun_tse = nm_mun_tse
  )

stopifnot(
  "crosswalk deveria ter 5.570 municípios (sem o exterior)" = nrow(crosswalk) == 5570,
  "cd_mun_tse não deveria ter duplicatas" = !anyDuplicated(crosswalk$cd_mun_tse),
  "cd_mun (IBGE) não deveria ter duplicatas" = !anyDuplicated(crosswalk$cd_mun)
)

write_parquet(crosswalk, file.path(AUX_DIR, "crosswalk_mun_tse_ibge.parquet"))
crosswalk







Checagem por nome (municípios novos/renomeados)
Nomes muito diferentes entre nm_mun_ibge e nm_mun_tse no mesmo cd_mun costumam indicar um município criado ou renomeado depois da tabela do crosswalk ter sido montada — checar à mão os que aparecerem aqui.

normaliza_texto &lt;- function(x) {
  x |&gt;
    stringr::str_to_upper() |&gt;
    stringi::stri_trans_general("Latin-ASCII") |&gt;
    stringr::str_squish()
}

divergencias &lt;- crosswalk |&gt;
  mutate(
    dist_nome = stringdist::stringdist(
      normaliza_texto(nm_mun_ibge), normaliza_texto(nm_mun_tse), method = "jw"
    )
  ) |&gt;
  filter(dist_nome &gt; 0.15) |&gt;
  arrange(desc(dist_nome))

divergencias

3. População adulta estimada por setor (pop18)
pop18(s) = total(s) − [0,4] − [5,9] − [10,14] − 0,6 × [15,19], a mesma conta de src/eleicoes/alocacao.pop18_por_setor() (Python) — ver PLAN.md &gt; Método, passo 4. É calculada aqui (R, etapa “auxiliares”) e só lida em Python, para não duplicar a leitura dos CSVs do Censo em duas linguagens.
Os CSVs do cn22-pop já vêm com os indicadores nomeados no padrão GeoReDUS (cn22_pop01_res_tot_0, cn22_pop03_0a4_tot_0, …), não com as variáveis brutas do IBGE (V0001, V01031, …) — a chave de setor ali é cod_setor, não cd_setor (confirmado rodando contra os arquivos reais em 25/09/2026; renomeado aqui para cd_setor, o nome usado no resto do pipeline).

pop01 &lt;- read_csv(file.path(CN22_POP_DIR, "cn22_pop01_abs.csv"), show_col_types = FALSE) |&gt;
  transmute(cd_setor = cod_setor, total = cn22_pop01_res_tot_0)

pop03 &lt;- read_csv(file.path(CN22_POP_DIR, "cn22_pop03_abs.csv"), show_col_types = FALSE) |&gt;
  transmute(
    cd_setor = cod_setor,
    fx_0a4 = cn22_pop03_0a4_tot_0,
    fx_5a9 = cn22_pop03_5a9_tot_0,
    fx_10a14 = cn22_pop03_10a14_tot_0,
    fx_15a19 = cn22_pop03_15a19_tot_0
  )

pop18_setor &lt;- pop01 |&gt;
  left_join(pop03, by = "cd_setor") |&gt;
  mutate(
    across(c(fx_0a4, fx_5a9, fx_10a14, fx_15a19), ~ replace(.x, is.na(.x), 0)),
    pop18 = pmax(total - fx_0a4 - fx_5a9 - fx_10a14 - 0.6 * fx_15a19, 0)
  ) |&gt;
  select(cd_setor, pop18)

write_parquet(pop18_setor, file.path(AUX_DIR, "pop18_setor.parquet"))
pop18_setor

4. Setores censitários 2022
O shapefile de setores 2022 do IBGE é grande demais para versionar; espera-se que já esteja em dados/01_bruto/aux/BR_Malha_Preliminar_2022.zip (baixado à mão, ver PLAN.md &gt; Fontes de dados), lido de dentro do zip sem extrair — o mesmo padrão de cnefe-etl/index.qmd (/vsizip/).

caminho_zip &lt;- "dados/01_bruto/aux/BR_Malha_Preliminar_2022.zip"

setores &lt;- st_read(
  paste0("/vsizip/", caminho_zip),
  quiet = TRUE
) |&gt;
  rename(cd_setor = CD_SETOR) |&gt;
  st_transform(4674)

st_write(setores, file.path(AUX_DIR, "setores_2022.gpkg"), delete_dsn = TRUE)

1. Download

url_locais &lt;- sprintf(
  "https://cdn.tse.jus.br/estatistica/sead/odsele/eleitorado_locais_votacao/eleitorado_local_votacao_%d.zip",
  ano
)
caminho_zip &lt;- file.path(BRUTO_DIR, sprintf("eleitorado_local_votacao_%d.zip", ano))

baixar_com_retry &lt;- function(url, destino, tentativas = 3) {
  if (file.exists(destino)) {
    return(invisible(destino))
  }
  for (tentativa in seq_len(tentativas)) {
    resultado &lt;- tryCatch(
      {
        resp &lt;- request(url) |&gt;
          req_user_agent("dados_eleicoes (CEM/USP)") |&gt;
          req_perform()
        writeBin(resp_body_raw(resp), destino)
        TRUE
      },
      error = function(e) {
        message(sprintf("Tentativa %d/%d falhou: %s", tentativa, tentativas, conditionMessage(e)))
        FALSE
      }
    )
    if (isTRUE(resultado)) break
    if (tentativa &lt; tentativas) Sys.sleep(2^tentativa)
  }
  if (!file.exists(destino)) stop("Não foi possível baixar ", url)
  invisible(destino)
}

baixar_com_retry(url_locais, caminho_zip)

3. Chaves e crosswalk
O arquivo real (confirmado em 28/09/2026, ver CLAUDE.md) traz uma linha por seção por turno (NR_TURNO), não uma linha por seção — então id_secao sozinho não é único; a chave completa da linha é (id_secao, nr_turno). O CD_MUNICIPIO já vem com 5 dígitos e zero à esquerda ("01120"), no mesmo formato do cd_mun_tse do crosswalk depois do str_pad() da etapa 00.

crosswalk &lt;- read_parquet("dados/02_processado/aux/crosswalk_mun_tse_ibge.parquet")

locais_com_chave &lt;- locais_bruto |&gt;
  mutate(
    nr_turno = as.integer(nr_turno),
    id_local_proprio = str_c(
      cd_municipio,
      str_pad(nr_zona, CRESCE_ZONA, pad = "0"),
      str_pad(nr_local_votacao, CRESCE_NUM, pad = "0")
    ),
    id_secao = str_c(
      cd_municipio,
      str_pad(nr_zona, CRESCE_ZONA, pad = "0"),
      str_pad(nr_secao, CRESCE_NUM, pad = "0")
    )
  ) |&gt;
  left_join(crosswalk, by = c("cd_municipio" = "cd_mun_tse"))

n_sem_crosswalk &lt;- sum(is.na(locais_com_chave$cd_mun) & locais_com_chave$sg_uf.x != "ZZ")
if (n_sem_crosswalk &gt; 0) {
  warning(n_sem_crosswalk, " locais sem crosswalk para município IBGE (fora do exterior).")
}


Seções agregadas: resolver o local pela seção principal
DS_TIPO_SECAO_AGREGADA tem três valores (contados no arquivo real de 2022): Principal (944.150 linhas), Agregada (48.326) e Distribuída de ofício (1.236). Só a Agregada tem NR_SECAO_PRINCIPAL de verdade (as outras trazem -1, sentinela de “não se aplica”). Em 952 das 48.326 (~2%) o NR_LOCAL_VOTACAO da própria linha “Agregada” diverge do local da seção principal — resolver pelo NR_SECAO_PRINCIPAL é obrigatório, não um detalhe cosmético. A resolução é feita dentro do mesmo nr_turno, porque a seção principal referenciada é a do mesmo turno.

locais_com_chave &lt;- locais_com_chave |&gt;
  mutate(
    id_secao_principal = if_else(
      nr_secao_principal != "-1",
      str_c(
        cd_municipio,
        str_pad(nr_zona, CRESCE_ZONA, pad = "0"),
        str_pad(nr_secao_principal, CRESCE_NUM, pad = "0")
      ),
      NA_character_
    )
  )

local_por_secao &lt;- locais_com_chave |&gt;
  distinct(id_secao, nr_turno, .keep_all = TRUE) |&gt;
  select(id_secao, nr_turno, id_local_da_secao = id_local_proprio)

locais_com_chave &lt;- locais_com_chave |&gt;
  left_join(
    local_por_secao,
    by = c("id_secao_principal" = "id_secao", "nr_turno" = "nr_turno")
  ) |&gt;
  mutate(id_local = coalesce(id_local_da_secao, id_local_proprio))

n_resolvidas_por_principal &lt;- sum(
  locais_com_chave$id_local != locais_com_chave$id_local_proprio
)
n_resolvidas_por_principal

[1] 1049

6. Municípios com mais de uma zona
Insumo para a camada id_zona_mun (PLAN.md &gt; Pesquisa &gt; Zonas eleitorais): só nesses municípios a geometria da zona precisa ser estimada.

n_zonas_mun &lt;- locais |&gt;
  distinct(cd_mun, nr_zona) |&gt;
  count(cd_mun, name = "n_zonas_mun") |&gt;
  arrange(desc(n_zonas_mun))

write_parquet(n_zonas_mun, file.path(PROCESSADO_DIR, sprintf("n_zonas_mun_%d.parquet", ano)))
head(n_zonas_mun, 10)
